import{_ as t,o,c as r,a5 as a}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"Encrypted S3 Material Repository, Storage Add-Ons, Client Folder Vault & Google Drive Sync","description":"","frontmatter":{},"headers":[],"relativePath":"feature/modules/04-task-chat-vault/s3-folder-vault-security/spec.md","filePath":"feature/modules/04-task-chat-vault/s3-folder-vault-security/spec.md"}'),d={name:"feature/modules/04-task-chat-vault/s3-folder-vault-security/spec.md"};function l(c,e,i,s,n,p){return o(),r("div",null,[...e[0]||(e[0]=[a('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Category Index</a> · <a href="./../../README.html">← Modules Master Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="encrypted-s3-material-repository-storage-add-ons-client-folder-vault-google-drive-sync" tabindex="-1">Encrypted S3 Material Repository, Storage Add-Ons, Client Folder Vault &amp; Google Drive Sync <a class="header-anchor" href="#encrypted-s3-material-repository-storage-add-ons-client-folder-vault-google-drive-sync" aria-label="Permalink to &quot;Encrypted S3 Material Repository, Storage Add-Ons, Client Folder Vault &amp; Google Drive Sync&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Module Slug</strong></td><td style="text-align:left;"><code>s3-folder-vault-security</code></td></tr><tr><td style="text-align:left;"><strong>Category</strong></td><td style="text-align:left;"><code>04-task-chat-vault</code> — Task Workflow, Realtime Workspace Chat &amp; Encrypted S3 Vault</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner, Manager, Creator, Client</code></td></tr><tr><td style="text-align:left;"><strong>Consolidated Feature Scopes</strong></td><td style="text-align:left;"><code>agency-storage-onboarding</code>, <code>pre-s3-encryption</code>, <code>s3-folder-vault-security</code>, <code>client-folder-sharing</code>, <code>client-drive-disconnect</code>, <code>client-drive-overflow</code>, <code>client-drive-workspace-sync</code>, <code>drive-import-authorization</code>, <code>library-simple-ux</code>, <code>manual-trash-purge</code>, <code>material-preview-recovery</code>, <code>mp4-upload-detection</code>, <code>trash-bulk-selection</code></td></tr><tr><td style="text-align:left;"><strong>Aligned SRS Domains</strong></td><td style="text-align:left;"><a href="./../../../srs/05-content-task-workflow/README.html">3.6 Content &amp; Workflow — Material Repository</a> (<code>3.6.11–3.6.18</code>)</td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified</td></tr></tbody></table><h2 id="_1-objective-architectural-motivation" tabindex="-1">1. Objective &amp; Architectural Motivation <a class="header-anchor" href="#_1-objective-architectural-motivation" aria-label="Permalink to &quot;1. Objective &amp; Architectural Motivation&quot;">​</a></h2><p>Unify BrandHub&#39;s enterprise media storage architecture: <strong>Pre-S3 Envelope Encryption</strong> (<code>RepositoryEnvelopeCrypto</code> + <code>RepositoryEncryptedMediaController</code>), hierarchical <strong>Folder &amp; Trash Vault</strong> (<code>MaterialController</code>, <code>MaterialFolderController</code>, <code>MaterialVersionController</code>), <strong>Agency Storage Quota &amp; SePay Storage Add-Ons</strong> (<code>StorageAddonController</code>), <strong>Client Private Vault &amp; Selective Workspace Folder Sharing</strong> (<code>ClientVaultController</code>), and <strong>Customer Google Drive Integration</strong> with paid S3 overflow &amp; folder import (<code>CustomerDriveController</code>, <code>DriveFolderImportController</code>).</p><h2 id="_2-user-stories" tabindex="-1">2. User Stories <a class="header-anchor" href="#_2-user-stories" aria-label="Permalink to &quot;2. User Stories&quot;">​</a></h2><ul><li>As an <code>Owner</code> or <code>Manager</code>, I want all Workspace media assets stored in an encrypted S3 folder hierarchy with strict quota reservations (<code>agency_storage_usage</code>), bulk trash purge, MP4 <code>ftyp</code> magic-byte detection, and purchasable S3 storage add-ons.</li><li>As a <code>Client</code>, I want my own private <strong>Client Vault</strong> (<code>client_vault_*</code>) to organize brand assets and selectively share folders into specific Agency Workspaces (<code>POST /client-vault/shares</code>), or connect Google Drive with automatic paid S3 overflow.</li></ul><h2 id="_3-consolidated-acceptance-criteria" tabindex="-1">3. Consolidated Acceptance Criteria <a class="header-anchor" href="#_3-consolidated-acceptance-criteria" aria-label="Permalink to &quot;3. Consolidated Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Pre-S3 Envelope Encryption (<code>pre-s3-encryption</code>, <code>s3-folder-vault-security</code>):</strong> <code>RepositoryEnvelopeCrypto</code> encrypts repository objects with per-object AES-256-GCM data keys wrapped by KMS/master envelope keys before S3 persistence (<code>RepositoryEncryptedMediaController</code> <code>/api/v1/repository-media</code>), enforcing strict tenant access checks before streaming decrypted previews/downloads (<code>material-preview-recovery</code>).</li><li><strong>Hierarchical Folders, MP4 Magic-Byte Detection &amp; Trash Governance (<code>library-simple-ux</code>, <code>mp4-upload-detection</code>, <code>trash-bulk-selection</code>, <code>manual-trash-purge</code>):</strong> <code>MaterialFolderController</code> (<code>/materials/browser</code>, <code>/folders/{id}/move|restore|purge</code>) and <code>MaterialController</code> (<code>/materials/trash/purge</code>, multipart upload sessions) validate MP4 (<code>isom</code>/<code>mp42</code>/<code>mp41</code>) &amp; QuickTime <code>.mov</code> boxes accurately, support multi-select trash restore/permanent purge, and release <code>agency_storage_usage</code> atomically via <code>material_quota_releases</code> + <code>material_audit_receipts</code>.</li><li><strong>Agency Storage Onboarding &amp; SePay Add-Ons (<code>agency-storage-onboarding</code>):</strong> <code>StorageAddonController</code> (<code>/api/v1/storage/addons</code>, <code>/checkout</code>, <code>/orders/{orderId}</code>) and <code>agency_storage_reservations</code> enforce byte-exact storage quotas across <code>system_storage_pools</code>, allowing <code>Owner</code> to purchase recurring/top-up S3 capacity via SePay.</li><li><strong>Client Private Vault &amp; Folder Sharing (<code>client-folder-sharing</code>):</strong> <code>ClientVaultController</code> (<code>/api/v1/client-vault/browser</code>, <code>/folders</code>, <code>/api/v1/workspaces/{workspaceId}/client-vault/shares</code>) gives <code>Client</code> accounts an isolated vault (<code>client_vault_storage_usage</code>) and revocable read/use folder shares into designated Workspaces.</li><li><strong>Customer Google Drive Sync, Import &amp; Paid S3 Overflow (<code>client-drive-overflow</code>, <code>client-drive-workspace-sync</code>, <code>client-drive-disconnect</code>, <code>drive-import-authorization</code>):</strong> <code>CustomerDriveController</code> (<code>/workspaces/{workspace}/storage/drive</code>) and <code>DriveFolderImportController</code> (<code>/materials/drive-import</code>) manage OAuth Drive binding, asynchronous folder imports, seamless fallback to paid Agency S3 when Drive quota overflows, and destructive-confirmed Drive disconnect.</li><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> Every user-facing string, tooltip, dialog prompt, status badge, and error banner uses key-parallel translations (<code>library.{folders,vault,encryption,trash,storageAddons,drive,clientVault}.*</code> in <code>src/i18n/locales/{vi,en}/library.json</code>) on <code>brandhub-web</code> and <code>tr()</code> (<code>en.json</code> + <code>vi/common.json</code>) on <code>brandhub-mobile-app</code> with zero hardcoded Vietnamese or English strings in JSX/TSX.</li><li><strong>Light &amp; Dark Mode Compliance:</strong> All surfaces, drawers, badges, charts, and interactive controls use semantic CSS variables / Tailwind <code>dark:</code> variants on Web and <code>useAppPreferences().palette</code> tokens on Mobile, achieving WCAG AA contrast in both Light and Dark themes.</li></ol><h2 id="_4-ui-ux-surfaces-lifecycle-states" tabindex="-1">4. UI / UX Surfaces &amp; Lifecycle States <a class="header-anchor" href="#_4-ui-ux-surfaces-lifecycle-states" aria-label="Permalink to &quot;4. UI / UX Surfaces &amp; Lifecycle States&quot;">​</a></h2><ul><li><strong>Web Surfaces (<code>brandhub-web</code>):</strong> <code>pages/library/*</code> (<code>CustomerDrivePanel.tsx</code>, <code>ConfirmSoftDeleteModal.tsx</code>, <code>ConfirmPermanentDeleteModal.tsx</code>, <code>LibraryResourceDropdown.tsx</code>)</li><li><strong>Mobile Surfaces (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/more/MediaLibraryScreen.tsx</code>, <code>src/services/materialService.ts</code>, <code>src/utils/repositoryFilters.ts</code></li><li><strong>UI States:</strong><ul><li><strong>Loading / Streaming:</strong> Deterministic skeleton placeholders, progress bars, and disabled submit buttons preventing duplicate requests.</li><li><strong>Empty / Onboarding:</strong> Contextual empty state with localized call-to-action and zero fabricated mock fallback data.</li><li><strong>Active / Realtime Sync:</strong> Scoped <code>TanStack Query</code> cache updates + WebSocket/SSE/polling synchronization where applicable.</li><li><strong>Error / Conflict Recovery:</strong> Actionable localized error banners (<code>400/403/404/409/429/503</code>) preserving unsaved user input.</li></ul></li></ul><h2 id="_5-api-messaging-protocol-contract" tabindex="-1">5. API, Messaging &amp; Protocol Contract <a class="header-anchor" href="#_5-api-messaging-protocol-contract" aria-label="Permalink to &quot;5. API, Messaging &amp; Protocol Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Route / Channel / Filter</th><th style="text-align:left;">Auth / Scope</th><th style="text-align:left;">Service &amp; Handler</th></tr></thead><tbody><tr><td style="text-align:left;"><code>GET/POST/PATCH/DELETE /api/v1/workspaces/{workspaceId}/materials/** &amp; /folders/**</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator, Client</code>)</td><td style="text-align:left;"><code>MaterialController</code>, <code>MaterialFolderController</code>, <code>MaterialVersionController</code> -&gt; folders, multipart upload, preview, versions &amp; bulk trash purge</td></tr><tr><td style="text-align:left;"><code>PUT/GET /api/v1/repository-media</code></td><td style="text-align:left;">Signed Internal / Authorized Stream</td><td style="text-align:left;"><code>RepositoryEncryptedMediaController</code> + <code>RepositoryEnvelopeCrypto</code> -&gt; envelope-encrypted S3 I/O</td></tr><tr><td style="text-align:left;"><code>GET /api/v1/storage/addons &amp; POST /checkout</code></td><td style="text-align:left;">Bearer (<code>Owner</code>)</td><td style="text-align:left;"><code>StorageAddonController</code> -&gt; S3 storage add-on plans &amp; SePay VietQR checkout</td></tr><tr><td style="text-align:left;"><code>GET/POST/PATCH/DELETE /api/v1/client-vault/** &amp; /workspaces/{id}/client-vault/shares/**</code></td><td style="text-align:left;">Bearer (<code>Client</code>; Workspace members read shared)</td><td style="text-align:left;"><code>ClientVaultController</code> -&gt; Client Vault folders &amp; selective Workspace sharing</td></tr><tr><td style="text-align:left;"><code>GET/POST/DELETE /api/v1/workspaces/{workspace}/storage/drive/** &amp; /materials/drive-import/**</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Client</code>)</td><td style="text-align:left;"><code>CustomerDriveController</code> &amp; <code>DriveFolderImportController</code> -&gt; Google Drive sync, overflow &amp; import jobs</td></tr></tbody></table><h2 id="_6-error-handling-security-edge-cases" tabindex="-1">6. Error Handling, Security &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-security-edge-cases" aria-label="Permalink to &quot;6. Error Handling, Security &amp; Edge Cases&quot;">​</a></h2><ul><li><strong>Upload Session Aborted / Expired:</strong> <code>DELETE /upload-session/{sessionId}</code> and background reaper abort incomplete S3 multipart uploads and release <code>agency_storage_reservations</code> so failed uploads never leak quota.</li><li><strong>Client Revokes Shared Vault Folder:</strong> Immediate revocation on <code>DELETE /client-vault/shares/{shareId}</code> blocks new Workspace downloads while preserving already-published external social posts.</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Aligned SRS Functional Requirements:</strong> <a href="./../../../srs/05-content-task-workflow/README.html">3.6 Content &amp; Workflow — Material Repository</a> (<code>3.6.11–3.6.18</code>)</li><li><strong>BA &amp; Architecture References:</strong> <a href="./../../../../ba/05-content-task-workflow.html">BA 05 Content &amp; Task Workflow</a> · <a href="./../../../../ba/10-roles-permissions-matrix.html">Roles &amp; Permissions Matrix</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Production code verified across backend, AI/publisher workers, Web, and Mobile; <code>vi.json</code> + <code>en.json</code> parity verified; Light/Dark mode audited; all automated verification suites in <a href="./test.html">test.md</a> passing.</li><li><strong>Out of Scope:</strong> De-scoped SRS items (livestream features, subscription plan downgrades, PayOS/VNPay/Stripe gateways, Zalo OA publishing, or copyright/plagiarism scanning).</li></ul>',19)])])}const m=t(d,[["render",l]]);export{u as __pageData,m as default};
